#include <iostream>

using namespace std;

int main() {
    int n;
    cin >> n;

    char nam[8];
    for (int i = 0; i < n; i++)
        cin >> nam[i];

    int pos = 0;
    for (int i = 0; i < n; i++) {
        if (nam[i] != '.') {
            pos = i;
            break;
        }
    }

    if (n == 8)
        cout << "vaporeon\n";
    else if (n == 6)
        cout << "espeon\n";
    else {
        char evs[6][8] = {
            "flareon", "glaceon", "leafeon",
            "umbreon", "jolteon", "sylveon"
        };

        switch (pos) {
            case 0:
            case 3:
                for (int i = 0; i < 6; i++) {
                    if (nam[pos] == evs[i][pos]) {
                        cout << evs[i] << endl;
                        break;
                    }
                }
                break;

            case 1:
                if (nam[pos] == 'l') {
                    for (int i = 0; i < 2; i++) {
                        if (nam[3] == evs[i][3]) {
                            cout << evs[i] << endl;
                            break;
                        }
                    }
                } else {
                    for (int i = 2; i < 6; i++) {
                        if (nam[pos] == evs[i][pos]) {
                            cout << evs[i] << endl;
                            break;
                        }
                    }
                }
                break;

            case 2:
                if (nam[pos] == 'a') {
                    for (int i = 0; i < 3; i++) {
                        if (nam[pos + 1] == evs[i][pos + 1]) {
                            cout << evs[i] << endl;
                            break;
                        }
                    }
                } else if (nam[pos] == 'l') {
                    for (int i = 4; i < 6; i++) {
                        if (nam[pos + 1] == evs[i][pos + 1]) {
                            cout << evs[i] << endl;
                            break;
                        }
                    }
                } else {
                    cout << "umbreon" << endl;
                }
                break;
        }
    }

    return 0;
}

