#include <iostream>
#include <string>
using namespace std;

int main() {
    int n;
    string pattern;
    cin >> n >> pattern;

    const string names[] = {
        "vaporeon", "jolteon", "flareon", "espeon",
        "umbreon", "leafeon", "glaceon", "sylveon"
    };

    for (int i = 0; i < 8; ++i) {
        if (names[i].size() != pattern.size())
            continue;

        bool matches = true;
        for (int j = 0; j < n; ++j) {
            if (pattern[j] != '.' && pattern[j] != names[i][j]) {
                matches = false;
                break;
            }
        }

        if (matches) {
            cout << names[i] << '\n';
            break;
        }
    }

    return 0;
}

